  ui_story_5061_50610202_6_dialog_content = "ฉันเคลื่อนไหวตามกระแสลูมินาเหมือนใบไม้ที่สะบัดในลม ทุกอย่างรู้สึกเหมือนเป็นธรรมชาติ...",
  ui_story_5061_50610202_7_dialog_content = "แต่ยังไงล่ะ? มันจะเป็นไปได้อย่างไรเนี่ย?! ฉันต้องรู้เพิ่มเติมเกี่ยวกับมัน! ฉันต้องรู้!!!",
  ui_story_5061_50610202_8_dialog_content = "คุณคงเป็นเซเลสไทต์ที่ฉันได้ยินเรื่องมาเรื่อยๆ ใช่มั้ยคะ! คุณอาจตอบคำถามของฉันได้หรือไม่? ฉันอยากเรียนรู้เพิ่มเติมเกี่ยวกับความสามารถของคุณ และประสบการณ์ในการควบคุมโคลอสซัส!",
  ui_story_5061_50610202_9_dialog_content = "ห-หยุดเสียวินาทีนะ! ฉันยินดีที่จะคุยกัน แต่เราควรแนะนำตัวกันก่อนมั้ยครับ? ฉันชื่อ PlayerName",
  ui_story_5061_50610202_10_dialog_content = "โอ้! ขอโทษนะ เรื่องนั้น ฉันมักจะตื่นเต้นไปหน่อยบ้าง... มันเป็นนิสัยเสียของฉัน แต่ฉันหวังว่ามันไม่ได้ทำให้คุณรำคาญหรืออะไรนะ?",
  ui_story_5061_50610202_11_dialog_content = "ฉันชื่อแอนโทนี และฉันเป็นนักวิชาการด้านภูมิปัญญาชาวบ้าน คุณมาที่นี่เพราะสัญญาณขอความช่วยเหลือที่ฉันส่งออกไปใช่ไหม?",
  ui_story_5061_50610202_12_dialog_content = "อากาศที่นี่รุนแรงมากจนฉันถูกกลบด้วยหิมะ สิ่งเดียวที่ทำได้คือนั่งรอจนกว่าจะได้ยินเสียงคนมาช่วย...",
  ui_story_5061_50610202_13_dialog_content = "ขอบคุณพระเจ้าที่ฉันได้ยินเสียงเธอมา!",
  ui_story_5061_50610202_14_dialog_content = "ถูกต้อง ฉันก็ไม่ได้สร้างสำหรับสภาพแวดล้อมประเภทนี้เช่นกัน ฉันไม่สามารถรับรู้ความสัมผัสใครอยู่ที่นี่ นึกว่าฉันกำลังช่วยคน แต่กลับกลายเป็นอิคลิพไซท์...",
  ui_story_5061_50610202_15_dialog_content = "เพื่อนก็พูดถึงเรื่องคนโดนกักตัวด้วยนะ ใช่มั้ย?",
  ui_story_5061_50610202_16_dialog_content = "ความจริงนะ! แต่สถานการณ์นี้... ยากที่จะเชื่อหน่อย มันแตกต่างจากที่ฉันคิดไว้เต็มที่เลย...",
  ui_story_5061_50610202_17_dialog_content = "ที่นี่ ตามฉันมาค่ะ",
  ui_story_5061_50610202_18_dialog_content = "โอ้ และระวังเรื่องหนามน้ำแข็งนะ บางอันมีอิคลิพไซท์ถูกกักขังอยู่ด้านใน",
  ui_story_5061_50610202_19_dialog_content = "แต่พวกมันเยอะมากเลย...",
