  ui_story_5061_50610202_22_dialog_content = "... เธอยังไม่ตายเหรอ?!",
  ui_story_5061_50610202_23_dialog_content = "ฉันเชื่อว่างั้น ใช่ค่ะ",
  ui_story_5061_50610202_24_dialog_content = "ถึงแม้ว่าจะถูกกักขังในน้ำแข็ง แต่ร่างกายของเธอไม่แสดงอาการใด ๆ ที่บ่งบอกว่าเธอตายเนื่องจากหนาวตาย",
  ui_story_5061_50610202_25_dialog_content = "ที่จริงแล้วดูเหมือนว่าเธอกำลังหลับอยู่เท่านั้น ดูเหมือนว่าห้องศพแช่แข็งนี้ไม่ต่างจากเตียงเลย...",
