  ui_story_5061_50610202_28_dialog_content = "ง่า... หือ...?",
  ui_story_5061_50610202_29_dialog_content = "เมื่อไหร่ที่ฉัน... หลับไป...?",
  ui_story_5061_50610202_30_dialog_content = "เกิดอะไรขึ้นเนี่ย? ฉันมี... เรื่องสำคัญที่ต้องทำ...",
