  ui_story_5061_50610202_47_dialog_content = "ขอบคุณที่พวกมันไม่มากเกินไป ฉันควรจะสามารถดึงดูดความสนใจของพวกมันให้เธอสามารถหนีไปได้",
  ui_story_5061_50610202_48_dialog_content = "คุณจะต่อสู้กับพวกเขาทั้งหมดด้วยตัวคุณเองหรือ?! พวกเขาไม่ได้สนใจในงานวิจัยของคุณนะครับ!",
  ui_story_5061_50610202_49_dialog_content = "ไม่ต้องห่วง ในฐานะเป็นคนครึ่งเทพ ฉันสามารถปกป้องตัวเองได้เป็นอย่างดี นอกจากนี้ ฉันยังเคยเผชิญกับสถานการณ์แบบนี้หลายครั้งแล้ว",
