  ui_story_5061_50610202_53_dialog_content = "ฉันคอยคุ้มครองเธอ! มาโชว์ให้เหล่าสัตว์ประหลาดเห็นว่าเมื่อเราปฏิบัติตามกระแสลูมินา จะเกิดอะไรขึ้น!",
