  ui_story_5061_50610302_33_dialog_content = "(ฉันไม่รู้เรื่องนี้เลยตอนที่มานอร์ธแลนด์... แอนโทนี่ก็ไม่ได้พูดถึงเรื่องนี้เลย)",
  ui_story_5061_50610302_34_dialog_content = "ฉันชื่อซาร์ยา พี่สาวฉัน อลิน่า เธอเป็นหัวหน้าของผู้ตรวจตรา บอกฉันที คุณจริง ๆ ไม่ได้เห็นใครอื่นอยู่นอกที่นี่เลยใช่ไหม?",
