  ui_story_5061_50610502_12_dialog_content = "(งั้นก็สมเหตุสมผล เมื่อคิดถึงการศึกษาที่เป็นทางการของเขาเพียงเมื่อเขายังเป็นเด็ก...)",
  ui_story_5061_50610502_13_dialog_content = "เขายังมีแผนผังที่วาดด้วยมืออยู่หลายแผ่นในนี้ด้วย \"ไม้ค้ำเดินป่าหลายฟังก์ชัน\"? ว้าว, ฉันไม่รู้เลยว่าคุณแอนโทนีออกแบบและสร้างไม้ค้ำเดินที่เขานำพาติดตัวเสมอนั้นเอง!",
  ui_story_5061_50610502_14_dialog_content = "ดูเหมือนว่าเขาผ่านการเปลี่ยนแปลงหลายรุ่นด้วย ตามบันทึกของเขา มันยังคงพังลงในระหว่างการต่อสู้กับอิคลิพไซท์...",
  ui_story_5061_50610502_15_dialog_content = "ดังนั้น เขาเน้นการเสริมแข็งการออกแบบในเวอร์ชันถัดไปหลายรุ่น... ซึ่งฟังดูไม่ค่อยเหมือน \"หลายฟังก์ชัน\" สำหรับฉันเลยนะ!",
  ui_story_5061_50610502_16_dialog_content = "ฉันรู้เรื่องนั้นดี! ในฐานะเป็นคนครึ่งเทพ ฉันสามารถปกป้องตัวเองได้เป็นอย่างดี นอกจากนี้ ฉันเคยอยู่ในสถานการณ์แบบนี้มากมายครั้งแล้ว!",
  ui_story_5061_50610502_17_dialog_content = "อย่างน้อยที่สุด ฉันควรจะสามารถอดทนการโจมตีของพวกมันได้ จนกว่าพวกมันจะหมดแรงเอง",
  ui_story_5061_50610502_18_dialog_content = "แต่เมื่อพูดถึงเขา... ความอดทนน่าจะเป็นฟังก์ชันที่มีประโยชน์ที่สุดสำหรับทุกสิ่ง",
  ui_story_5061_50610502_19_dialog_content = "PlayerName? มันยังกล่าวถึงสิ่งที่เรียกว่า \"ฟังก์ชันของตัวส่งสัญญาณ\" นั่นหมายความว่าอะไรเหรอ?",
  ui_story_5061_50610502_20_dialog_content = "<size=45>ระวัง! อิคลิพไซท์!</size>",
  ui_story_5061_50610502_21_dialog_content = "อิคลิพไซท์?! ที่ไหนนะ?!?",
  ui_story_5061_50610502_22_dialog_content = "ฮ่าฮ่า, โดนเข้าให้แล้ว! นายนี่ขี้ขลาดจริงๆ!",
  ui_story_5061_50610502_23_dialog_content = "นี่เองคุณสองคน! ครอบครัวของคุณเป็นห่วงจนไม่สบาย! ก่อนจะหายไปจากหมู่บ้าน คุณไม่สามารถบอกพวกเขาว่าคุณกำลังไปที่ไหนได้หรือเปล่า?",
  ui_story_5061_50610502_24_dialog_content = "เธอถูกต้องนะ! การล้อเล่นแบบนี้ก็ไม่น่ารักเหมือนกันเลย!",
  ui_story_5061_50610502_25_dialog_content = "เด็กที่ร้องไห้เรียก Eclipsites เพื่อเรียกร้องความสนใจ มักจะเป็นคนแรกที่โดนกิน!",
  ui_story_5061_50610502_26_dialog_content = "เฮ้ย, ทำไมคุณพูดเหมือนคุณย่าของฉันเนี่ย? ไม่มีใครทำให้เด็กกลัวแบบนี้ในปัจจุบันหรอก!",
  ui_story_5061_50610502_27_dialog_content = "อีกทั้ง เรารู้จักพื้นที่นี้เหมือนหน้ามือเป็นหลังมือ เราเข้าใจอย่างดีว่าที่ไหนเสี่ยงและที่ไหนปลอดภัย",
  ui_story_5061_50610502_28_dialog_content = "ถ้าคุณไม่เชื่อเรา เราสามารถโชว์ท่าพิเศษของเราให้คุณดู—<color=#FFB400>การตกปลาอิคลิพไซท์</color>!",
  ui_story_5061_50610502_29_dialog_content = "อยากดูมั้ย? เราดึงความสนใจให้ Eclipsites ไล่ล่าเรา แล้วนำพวกมันเข้าสู่แสงของป้อมไฟ และ แบม! อิคลิพไซท์ก็กลายเป็นขนมปังกรอบ!",
  ui_story_5061_50610502_30_dialog_content = "และบางอิคลิพไซท์ก็สุดท้ายที่รู้เรื่องแล้ววิ่งหนีเหมือนไก่ตัวน้อย ๆ - ไม่สามารถบรรยายความตลกได้เลย ฮ่าๆๆ!",
  ui_story_5061_50610502_31_dialog_content = "เด็กๆ คิดอะไรกันอยู่เนี่ย?! นั่นอันตรายเกินไปนะ!",
  ui_story_5061_50610502_32_dialog_content = "เด็ก ๆ คนนี้จริง ๆ ไม่เข้าใจว่าพวกเขาโชคดีแค่ไหนที่ได้ใช้ชีวิตอยู่ในความสงบ...",
  ui_story_5061_50610502_33_dialog_content = "เพราะที่นี่น่าเบื่อมาก คุณรู้ไหม ไม่มีอะไรน่าสนใจมากในชายแดนนี้",
