  ui_story_5061_50610502_43_dialog_content = "นั่นหมายความว่าในขณะหนึ่ง ๆ นอร์ธแลนด์เคยเป็นที่อบอุ่น! อาจจะเคยมีฤดูใบไม้ผลิที่แท้จริงด้วย!",
  ui_story_5061_50610502_44_dialog_content = "นั่นหมายความว่านิทานเป็นเรื่องจริง ไม่ใช่แค่เรื่องที่แต่งขึ้นมาหลอกเด็กๆ! ฉันจะไปบอกย่าเรื่องนี้!",
  ui_story_5061_50610502_45_dialog_content = "แต่ก็ยังงงเสียอีก ทำไมนอร์ธแลนด์ถึงหนาวขนาดนี้ตอนนี้ล่ะ?",
  ui_story_5061_50610502_46_dialog_content = "เอาล่ะ นอร์ธแลนด์ยังตั้งอยู่ในความสูงมาก นอกจากนี้ยังอยู่ใกล้กับดินแดนรัตติกาลนิรันดร์ด้วย ซึ่งเราแน่ใจว่าเป็นสถานที่ที่หนาวมากเช่นกัน",
  ui_story_5061_50610502_47_dialog_content = "แท้จริงแล้ว หากนอร์ธแลนด์เคยเป็นสถานที่อบอุ่น... นั่นหมายความว่าวงกลมทวีคที่เรารู้จักกันนั้นไม่ได้อยู่ที่นี่...",
  ui_story_5061_50610502_48_dialog_content = "โลกนั้นหน้าตาเป็นอย่างไรกันแน่ในหลายปีที่ผ่านมา...?",
