  ui_story_5061_50610602_23_dialog_content = "เราคงไม่รู้จนกว่าจะถามแอนโทนีเอง...",
  ui_story_5061_50610602_24_dialog_content = "แต่ถ้าฉันต้องเดา ลูมินาแปลก ๆ นี้คงเป็นเหตุผลที่คุณมีพลังในการแช่แข็งภูเขาทั้งหลังได้",
  ui_story_5061_50610602_25_dialog_content = "และจากที่ฉันรู้สึกได้ ลูมิน่าแปลก ๆ นี้มาจากใต้ดินบางที่ มันอาจจะเชื่อมต่อกับแหล่งลูมิน่าเดียวกันที่ทำให้เกิดออโรร่าสตอร์ม",
  ui_story_5061_50610602_26_dialog_content = "แอนโทนีกล่าวว่าปัญหาบางส่วนคือขาดข้อมูลเกี่ยวกับ Aurorastorm ในช่วงเวลาล่าสุด... ซึ่งหมายความว่าเราไม่รู้ว่าเหตุการณ์นั้นเกิดขึ้นนานแค่ไหนแล้ว",
  ui_story_5061_50610602_27_dialog_content = "แต่ไม่ว่ามันจะเกิดขึ้นเมื่อไหร่ ก็ไม่มีร่องรอยที่เหลืออยู่แล้ว...",
  ui_story_5061_50610602_28_dialog_content = "ไม่มีร่องรอยของผู้ตรวจตราหรือการต่อสู้ที่พวกเขาต่อสู้กันในขณะนั้นเช่นกัน...",
  ui_story_5061_50610602_29_dialog_content = "ฉันไม่เชื่อว่าความทรงจำของฉันจะไม่น่าเชื่อถือเพียงนี้...",
  ui_story_5061_50610602_30_dialog_content = "(เฮ้? ดูเหมือนหิมะที่อยู่ใต้เท้าเรากำลังส่องแสงเลย...)",
  ui_story_5061_50610602_31_dialog_content = "หืม? นั่นกระต่ายข้างๆต้นไม้ที่นู่นเหรอ?",
  ui_story_5061_50610602_32_dialog_content = "กระต่ายเป็นสัตว์ที่ระมัดระวังมาก ถ้ามันอยู่นอกที่นี้ พื้นที่นี้ควรจะปลอดภัยจากอันตรายที่มองไม่เห็น...",
  ui_story_5061_50610602_33_dialog_content = "รอสักครู่นะซาร์ย่า! ที่นี่มีบางอย่างไม่ถูกต้อง ขอฉันลองใช้พลังของฉันก่อนดู",
  ui_story_5061_50610602_34_dialog_content = "อีกแล้วเหรอ? ก็ได้... ถ้าเกิดปัญหาขึ้นมาจริง ๆ ฉันจะสู้กับอะไรก็ตามที่คุณหามาให้",
  ui_story_5061_50610602_35_option_content = "บูสต์พลัง",
  ui_story_5061_50610602_36_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610602_37_dialog_content = "อ๊าก!",
  ui_story_5061_50610602_38_dialog_content = "นั่นคืออะไรเนี่ย?! เหมือนมีอะไรแทงหัวฉันเข้าไปเสียง...",
  ui_story_5061_50610602_39_dialog_content = "ย-อย่าทำให้ฉันกลัวแบบนั้นสิ! คุณ... ไหวมั้ย?",
  ui_story_5061_50610602_40_dialog_content = "ฉ...ฉันคิดว่าฉันอาจจะปลุกบางสิ่งขึ้นมา...",
  ui_story_5061_50610602_41_dialog_content = "<color=#e8d9bb>รัมเบิ้ล—!</color>",
  ui_story_5061_50610602_42_dialog_content = "เกิดอะไรขึ้น? เมื่อกี๊เสียงอะไรน่ะ?!",
  ui_story_5061_50610602_43_dialog_content = "พื้นกำลังถล่ม!",
  ui_story_5061_50610602_44_dialog_content = "ซาร์ย่า ระวัง!",
  ui_story_5061_50610602_45_dialog_content = "<color=#e8d9bb>ปัง—!</color>",
  ui_story_5061_50610602_46_dialog_content = "... อ๊อฟ!",
  ui_story_5061_50610602_47_dialog_content = "มันไม่เจ็บเท่าที่คิดไว้เลยนะ",
  ui_story_5061_50610602_48_dialog_content = "(ไม่... มันรู้สึกเหมือนมีบางอย่างจับเราขณะที่เรากำลังตกลงมา...)",
  ui_story_5061_50610602_49_dialog_content = "...",
  ui_story_5061_50610602_50_dialog_content = "(ด้วยวิธีนั้น มันดูปลอดภัยพอใช่มั้ย?)",
  ui_story_5061_50610602_51_dialog_content = "ไง ซาร์ยา เราควร...",
  ui_story_5061_50610602_52_dialog_content = "ไม่นะ, เธอหนาว...",
  ui_story_5061_50610701_1_dialog_content = "ซารย่า อยู่บ้านวันนี้นะ อย่าไปไหนเลย โอเค?",
  ui_story_5061_50610701_2_dialog_content = "แต่ฉันไม่ได้ออกจากบ้านมาหลายวันแล้ว...",
  ui_story_5061_50610701_3_dialog_content = "ทำไมคุณถึงชอบออกไปข้างนอกเสมอล่ะ? คุณไม่มีเพื่อนหรือครอบครัวที่จะดูแลคุณ หรือว่าคุณวางแผนที่จะก่อความวุ่นวายด้วยลูมินาติกส์อีกครั้งเหรอ?",
  ui_story_5061_50610701_4_dialog_content = "คุณยังจำได้ไหมว่าครั้งก่อนคุณแช่แข็งรถม้า? ไม่ควรให้เกิดเรื่องแบบนั้นอีกเลย!",
  ui_story_5061_50610701_5_dialog_content = "ฉัน... เข้าใจแล้วค่ะ ขอโทษนะคะ คุณพ่อ",
  ui_story_5061_50610701_6_dialog_content = "(อีกวันเหงาๆ ในห้องของฉัน...)",
  ui_story_5061_50610701_7_dialog_content = "โอ้ ซาร์ย่า ดูดอกไม้เหล่านี้สิ—เอ่อ, ทำไมเธอดูเศร้าแบบนั้นล่ะ?",
  ui_story_5061_50610701_8_dialog_content = "อลิน่า... วันนี้พ่อไม่ยอมให้ฉันออกจากบ้านอีกครั้ง...",
  ui_story_5061_50610701_9_dialog_content = "... พ่อแค่ยุ่งกับงานเกินไปจนไม่มีเวลาคิดถึงอะไรอื่นเลยนะซารย่า",
  ui_story_5061_50610701_10_dialog_content = "เขากลัวว่าเขาจะไม่ได้อยู่ใกล้เวลาที่คุณต้องการความช่วยเสียง ถ้าเกิดอะไรขึ้นกับคุณ เขาไม่รู้วิธีอื่นในการปกป้องคุณ",
  ui_story_5061_50610701_11_dialog_content = "ฉันรู้... ทุกอย่างเกิดขึ้นเพราะฉันควบคุม Luminatics ไม่ได้ ฉันเป็นปัญหาเท่านั้น...",
  ui_story_5061_50610701_12_dialog_content = "ไม่ใช่เรื่องจริงนะ ซาร์ย่า นอกจากนี้ฉันก็เคยมีปัญหาเดียวกัน ฉันยังเคยแช่แข็งประตูหน้าโดยไม่ได้ตั้งใจเลย!",
  ui_story_5061_50610701_13_dialog_content = "ฉันไม่อยากให้ใครรู้เลย นั่นเป็นเหตุผลที่ฉันจะเตะประตูเปิดก่อนเสมอ! ฮ่าๆๆ!",
  ui_story_5061_50610701_14_dialog_content = "เฟ่อ, คุณหลอกฉันไม่ได้นะ อลิน่า กัปตันหน่วยลาดตระเวนแบบไหนที่ควบคุมพลังของตัวเองไม่ได้เลย?",
  ui_story_5061_50610701_15_dialog_content = "แน่นอนว่าฉันสามารถควบคุมพวกมันได้ตอนนี้ แต่เธอก็แข็งแกร่งกว่าฉันเมื่ออยู่ในวัยเดียวกันกับเธอนะ",
  ui_story_5061_50610701_16_dialog_content = "ในความเป็นจริง ด้วยความสามารถของคุณ คุณยังสามารถกลายเป็นทหารรักษาพระองค์ในศาลาของราชินีเบธเลเฮมได้!",
  ui_story_5061_50610701_17_dialog_content = "ราชองครักษ์...? แต่นั่นก็เป็นความฝันของคุณอลิน่าตลอดเวลานะ...",
  ui_story_5061_50610701_18_dialog_content = "แต่การเป็นผู้ลาดตระเวนก็ยอดเยี่ยมเช่นกัน! ฉันสามารถเห็นสถานที่หลากหลายที่ห่างไกล เช่น ภูเขาที่มีหิมะ และแม้กระทั่งน้ำพุร้อน...",
  ui_story_5061_50610701_19_dialog_content = "และนั่นคงไม่แย่กว่าการทำงานในศาลเลยใช่ไหม?",
  ui_story_5061_50610701_20_dialog_content = "เธอน่าทึ่งจริง ๆ อลิน่า... เธอมีพลังและแรงจูงใจเต็มไปหมดเสมอ ไม่เหมือนกับพี่สาวที่เศร้าและไร้ประโยชน์ของเธอ",
  ui_story_5061_50610701_21_dialog_content = "ไม่ต้องกังวลนะ ซาร์ย่า! เร็ว ๆ นี้เธอจะแข็งแกร่งเท่ากันกับฉัน... ไม่ แม้กระทั่งแข็งแกร่งกว่า!",
  ui_story_5061_50610701_22_dialog_content = "นอกจากนี้ ฉันยังไม่ยอมยกเลิกความฝันของฉัน ฉันมั่นใจว่าฉันจะกลายเป็นราชการป้อมยามในวันหนึ่ง!",
  ui_story_5061_50610701_23_dialog_content = "และเมื่อวันนั้นมาถึง ฉันจะปกป้องนอร์ธแลนด์คู่กับราชินี!",
  ui_story_5061_50610701_24_dialog_content = "ฮี่ฮี่! ฉันรู้ว่าคุณทำได้!",
  ui_story_5061_50610701_25_dialog_content = "โอ๊ะ! ดูเหมือนว่าฉันคุยนานเกินไปนิดหน่อย ถึงเวลาเกือบจะไปเจอกับคนลาดตระเวนคนอื่น ๆ แล้ว!",
  ui_story_5061_50610701_26_dialog_content = "โอ้ไม่! คุณควรรีบเข้า อลิน่า... โชคดีในภารกิจของคุณนะ!",
  ui_story_5061_50610701_27_dialog_content = "ขอบคุณนะ พยายามสู้ๆ นะครับ/ค่ะ? อย่าลืมว่าเวลาพ่อโกรธ อย่าเอาคำพูดของเขามาใส่ใจมากเกินไปนะ!",
  ui_story_5061_50610701_28_dialog_content = "(... แล้วเธอก็หายไป...)",
  ui_story_5061_50610701_29_dialog_content = "(ถ้าฉันรู้ว่าเกิดอะไรขึ้นต่อไป... ฉันคงไม่ปล่อยให้เธอออกไป)",
  ui_story_5061_50610701_30_dialog_content = "(... แต่อดีตไม่สามารถเปลี่ยนแปลงได้ ในความเศร้าใจและความเสียใจของฉัน สิ่งที่ฉันสามารถทำได้เพียงแค่เสี่ยงชีวิตเพื่อแก้ไขสิ่งที่ผิดพลาด...)",
  ui_story_5061_50610701_31_dialog_content = "(ตำแหน่งที่รู้จักล่าสุดของทีมลาดตระเวนของเธอ... กำลังถูกอิคลิพไซท์รุมเร้า...)",
  ui_story_5061_50610701_32_dialog_content = "อลิน่า! คุณอยู่ข้างนอกใช่ไหม?!",
  ui_story_5061_50610701_33_dialog_content = "โรอา—",
  ui_story_5061_50610701_34_dialog_content = "อย่ามาขวางทางฉันนะ!",
  ui_story_5061_50610701_35_dialog_content = "อลิน่า! ตอบฉันทีค่ะ!",
  ui_story_5061_50610701_36_dialog_content = "กรร!",
  ui_story_5061_50610701_37_dialog_content = "เคลื่อนไหว!",
  ui_story_5061_50610701_38_dialog_content = "พี่สาวคะ... พี่... ยังอยู่ใช่ไหม? ฉันกลัวมาก...",
