  ui_story_5061_50610701_40_dialog_content = "...!",
  ui_story_5061_50610701_41_dialog_content = "เสียงนั้น... นั่นคุณอลิน่าเหรอ?",
  ui_story_5061_50610701_42_dialog_content = "... เธอต้องการช่วยคนหรือเปล่า?",
  ui_story_5061_50610701_43_dialog_content = "ใช่! ฉัน... ฉันอยากช่วยน้องสาวของฉัน!",
