  ui_story_5061_50610701_48_dialog_content = "(ฉันคิดว่ามันจะพาฉันไปหาพี่สาวของฉัน แต่แทนที่จะเป็นเช่นนั้น... มันพาฉันไปสู่นรกที่ฉันไม่เคยคิดฝันเสียก่อน)",
  ui_story_5061_50610701_49_dialog_content = "<color=#e8d9bb>ผู้ควบคุมที่นับไม่ถ้วนนอนอยู่บนพื้นโดยไม่มีการเคลื่อนไหว</color>",
  ui_story_5061_50610701_50_dialog_content = "<color=#e8d9bb>อิคลิพไซท์ที่มีคมเขี้ยวกว้างและเสียงร้องดังกระจ่าง</color>",
  ui_story_5061_50610701_51_dialog_content = "<color=#e8d9bb>กลิ่นเหม็นน่าสะอิดสะเอียน ยังคงแทะทะลุ แม้ในหิมะที่หวนวนอยู่</color>",
  ui_story_5061_50610701_52_dialog_content = "<color=#e8d9bb>และห้วงอเวจีที่คล้ายห้วงลึก ความเหนียว และน่าสะอิดสะเอียนบนพื้นดิน</color>",
  ui_story_5061_50610701_53_dialog_content = "นี่ไม่ใช่เรื่องจริง... มันเป็นไปไม่ได้...",
  ui_story_5061_50610701_54_dialog_content = "ไอ้สัตว์สกปรก! อย่าเข้ามาใกล้น้องสาวของฉัน!",
