  ui_story_5061_50610701_57_dialog_content = "พวกมันเยอะเกินไป! ฉันเอาชนะไม่ได้ทั้งหมด!",
  ui_story_5061_50610701_58_dialog_content = "โรอาาาาา—",
  ui_story_5061_50610701_59_dialog_content = "ขอโทษนะ อลิน่า... ฉันคิดว่าฉันไม่สามารถฆ่า Eclipsites เหล่านี้ทั้งหมดได้!",
  ui_story_5061_50610701_60_dialog_content = "ถ้าฉันแข็งแกร่งขึ้น ฉันอาจจะช่วยคุณได้ตอนนี้...",
  ui_story_5061_50610701_61_dialog_content = "อลิน่า... อลิน่า! ม่ายยยยย!!!",
  ui_story_5061_50610701_62_dialog_content = "<size=45>อลิน่า!!!</size>",
  ui_story_5061_50610701_63_dialog_content = "... ซาร์ย่า! ตื่นสิ!",
  ui_story_5061_50610701_64_dialog_content = "อลิน่า!",
  ui_story_5061_50610701_65_dialog_content = "ใจเย็น ๆ นะครับ ซารย่า! มันเป็นแค่ฝันร้ายเท่านั้น!",
  ui_story_5061_50610701_66_dialog_content = "...",
  ui_story_5061_50610701_67_dialog_content = "คุณจำได้ไหมว่าพื้นดินถล่มใต้เท้าเรา? ผมคิดว่าเราตกลงมาในถ้ำบางแห่ง",
  ui_story_5061_50610701_68_dialog_content = "ดูเหมือนว่าจะมีซากโบราณถูกกักขังในน้ำแข็งที่นี่ เราจะลงไปดูใกล้ ๆ กัน...",
  ui_story_5061_50610701_69_dialog_content = "โรอา—",
  ui_story_5061_50610701_70_dialog_content = "อ๊ะ! อิ-อิคลิพไซท์! โอ้ไม่, เราควรทำอะไรดี? ฉันต่อสู้กับพวกเขาทั้งหมดไม่ได้...",
