  ui_story_5061_50611001_44_dialog_content = "<color=#FFB400>ประภาคาร</color> ซึ่งส่งออกแสงกำแพงป้องกันอิคลิพไซท์ให้กับอาณาจักรของเราทั้งหมด ยังเป็นส่วนหนึ่งของประกายไฟด้วย",
