  ui_story_5061_50611101_9_dialog_content = "พูดอะไรน่ะ?!",
  ui_story_5061_50611101_10_dialog_content = "คุณไม่ได้พูดว่าคุณปกป้องทุกคนด้วยความช่วยเสริมจากพี่สาวของฉันเหรอ?",
  ui_story_5061_50611101_11_dialog_content = "อย่าบอกนะว่าลืมแล้วเหรอ?!",
  ui_story_5061_50611101_12_dialog_content = "เทมเพลตเริ่มต้นใหม่... เผชิญกับข้อผิดพลาดที่ไม่ทราบสาเหตุ;",
  ui_story_5061_50611101_13_dialog_content = "มาเถอะทุกคน",
  ui_story_5061_50611101_14_dialog_content = "เราต้องลดระดับลงอย่างเบา ๆ ที่สุดเท่าที่จะทำได้...",
  ui_story_5061_50611101_15_dialog_content = "ฉันเห็นก้นแล้ว!",
  ui_story_5061_50611101_16_dialog_content = "ดูสิ! นี่คุณซาร์ย่า!",
  ui_story_5061_50611101_17_dialog_content = "ซาร์ย่า! เรากลับมาเพื่อช่วยคุณ!",
  ui_story_5061_50611101_18_dialog_content = "อะไร...? ทำไม? คุณรู้มั้ยว่ามันยากขนาดไหนที่จะช่วยคุณออกจากที่นี่?!",
  ui_story_5061_50611101_19_dialog_content = "ก็บอกแล้วไง! คุณไม่ได้อยู่คนเดียวอีกต่อไป!",
