  ui_story_5061_50611101_22_dialog_content = "... แผนเหรอ?",
  ui_story_5061_50611101_23_dialog_content = "คุณยังไม่สังเกตเหรอว่าลูมินาของคุณไม่หายไปอีกแล้ว?",
  ui_story_5061_50611101_24_dialog_content = "... จริงด้วย!",
  ui_story_5061_50611101_25_dialog_content = "ตอนนี้เราต้องทำเพียงแค่จำกัดการเคลื่อนไหวของหมายเลข 33",
  ui_story_5061_50611101_26_dialog_content = "เมื่อเราทำแล้ว ฉันจะรอช่วงเวลาที่เหมาะสมในการใช้พลังของฉันกับเธอ!",
  ui_story_5061_50611101_27_dialog_content = "คุณเสียสติหรือไง PlayerName?! คุณลืมแล้วหรือว่ามันทำให้คุณเป็นอย่างไร?!",
  ui_story_5061_50611101_28_dialog_content = "หมายเลข 33 มี<color=#FFB400>เทมเพลตเอคโค่ที่สร้างข้อผิดพลาดอยู่ตลอดเวลา</color> เนื่องจากความเสียหายที่เธอได้รับ และการเปิดใช้งานที่ไม่เป็นปกติ",
  ui_story_5061_50611101_29_dialog_content = "คนเดียวที่สามารถซ่อมเทมเพลตเอคโค่ของเธอได้คือ PlayerName และต้องใช้พลังของเขาเท่านั้น",
  ui_story_5061_50611101_30_dialog_content = "เรายังได้รับการปกป้องจาก<color=#FFB400>เขา</color>ด้วย ดังนั้นเราไม่ควรพบกับความต้านทานเพิ่มเติม",
