  ui_story_5061_50611102_10_dialog_content = "(ในโลกความเป็นจริง ทุกอย่างนี้เกิดขึ้นภายในเวลาเดียว แต่มันรู้สึกเหมือนว่าจิตใจของฉันล่องลอยอย่างไม่มีที่สิ้นสุดในทะเลของเวลา—)",
  ui_story_5061_50611201_1_dialog_content = "<color=#e8d9bb>█████ ปีก่อน ที่สถานีจ่ายพลังงานประกายไฟ หมายเลข ███</color>",
  ui_story_5061_50611201_2_dialog_content = "เลนส์เสริมคลาดเคลื่อนครั้งที่ 4682; ความยาวโฟกัสต้องการการปรับเทียบใหม่",
  ui_story_5061_50611201_3_dialog_content = "...",
  ui_story_5061_50611201_4_dialog_content = "การสอบเทียบไม่สำเร็จ เหตุผล: ความเสียหายที่ไม่สามารถซ่อมแซมได้ในตัวรองเลนส์ช่วยหมายเลข 44.",
  ui_story_5061_50611201_5_dialog_content = "วิธีแก้: เปลี่ยนด้วยการสนับสนุนสำรองหมายเลข 863",
  ui_story_5061_50611201_6_dialog_content = "... ส่วนที่เสียหายถูกเปลี่ยนแล้ว สินค้าคงเหลือ: 3,264 หน่วย",
  ui_story_5061_50611201_7_dialog_content = "ตรวจสอบเสร็จสิ้น; ไม่พบความผิดปกติ การบำรุงรักษาประจำวันนี้เสร็จสมบูรณ์ด้วย",
  ui_story_5061_50611201_8_dialog_content = "<color=#e8d9bb>หมายเลข 33 ได้รับมอบหมายให้ดูแลอุปกรณ์ต่าง ๆ ภายในสถานที่ขนาดเล็กที่เธออยู่ โดยเฉพาะเครื่องมือสำหรับเข้มข้นลูมินา</color>",
  ui_story_5061_50611201_9_dialog_content = "<color=#e8d9bb>ตั้งแต่เธอตื่นขึ้นในสถานที่นี้ เธอก็ทำงานซ่อมบำรุงอย่างขยันขันแข็ง และปฏิบัติภารกิจที่ได้รับอย่างศรัทธา</color>",
  ui_story_5061_50611201_10_dialog_content = "ท่อลูมินาติดขัดครั้งที่ 78,643 และต้องการการขจัดสิ่งกีดขวาง",
  ui_story_5061_50611201_11_dialog_content = "... พยายามขอให้ผ่านล้มเหลว เหตุผล: ความเสียหายที่ซ่อมแซมไม่ได้ในท่อต่อส่วนที่ 65 ของระบบท่อส่งข้อมูล.",
  ui_story_5061_50611201_12_dialog_content = "วิธีแก้: แทนที่ด้วยท่อสำรอง 264; สต็อกคงเหลือ: 0 หน่วย",
  ui_story_5061_50611201_13_dialog_content = "ค้นหาท่อส่งทางเลือกเพื่อใช้งาน ท่อส่ง 195, สินค้าคงคลัง: 0 หน่วย; ท่อส่ง 236, สินค้าคงคลัง: 0 หน่วย",
  ui_story_5061_50611201_14_dialog_content = "ไม่มีท่อทดแทนที่ใช้งานได้; กำลังค้นหาท่อที่ใช้งานอยู่ที่เหมาะสมสำหรับการแทนที่...",
  ui_story_5061_50611201_15_dialog_content = "พบท่อที่เหมาะสมที่ส่วนต่อของสาขา 80 มีอัตราการเสื่อมสภาพ 39% กำลังเตรียมนำออกและเปลี่ยนใหม่เข้าสู่ส่วนต่อ 65",
