  ui_story_5061_50611201_18_dialog_content = "...",
  ui_story_5061_50611201_19_dialog_content = "(... เพื่อเปลี่ยนชิ้นส่วนของเครื่องมือกั้นลูมินา อุปกรณ์รอบ ๆ ถูกแยกส่วนทั้งหมด ...)",
  ui_story_5061_50611201_20_dialog_content = "<color=#e8d9bb>แต่หมายเลข 33 ไม่ใช่แค่เครื่องจักรเท่านั้น; เธอคือออโรเรียนที่ร่างกายและอวัยวะถูกดัดแปลงอย่างมาก</color>",
  ui_story_5061_50611201_21_dialog_content = "<color=#e8d9bb>เมื่อเวลาผ่านไป เธอก็เริ่มรู้สึกเหงา และเบื่อกับชีวิตที่ไม่เปลี่ยนแปลงในสถานที่ใต้ดิน</color>",
  ui_story_5061_50611201_22_dialog_content = "<color=#e8d9bb>แล้วเธอก็เริ่มสงสัยเป้าหมายของภารกิจของตัวเอง</color>",
  ui_story_5061_50611201_23_dialog_content = "... เนื่องจากการถอดแหล่งพลังงานสำรอง ระบบทำความร้อนไม่ได้ทำงานมา 436 วันแล้ว",
  ui_story_5061_50611201_24_dialog_content = "(คงต้องหนาวมากเลยตอนนี้... แต่ฉันไม่สามารถรู้สึกถึงความหนาวอีกต่อไป...)",
  ui_story_5061_50611201_25_dialog_content = "(... ทุกสิ่งที่ฉันทำไป มีความหมายจริงหรือเปล่า?)",
  ui_story_5061_50611201_26_dialog_content = "(ผ่านมาหลายปีแล้ว ไม่มีใครมาที่นี่หรือรู้ว่าฉันทำอะไรอยู่เลย)",
  ui_story_5061_50611201_27_dialog_content = "(ฉันยังต้องดำเนินภารกิจต่อไปหรือไม่?)",
  ui_story_5061_50611201_28_dialog_content = "ค้นหาโมดูลจัดเก็บข้อมูลทางเลือกที่สามารถแทนที่โมดูลปัจจุบันที่ใช้อยู่",
  ui_story_5061_50611201_29_dialog_content = "ไม่มีโมดูลเก็บข้อมูลที่ไม่ได้ใช้งาน ค้นหาโมดูลที่สามารถแทนที่ในการใช้งานปัจจุบัน...",
  ui_story_5061_50611201_30_dialog_content = "อุปกรณ์บำรุงรักษาชีวภาพของหมายเลข 33, หัว, โมดูลเก็บข้อมูล 2, มีอัตราการเสื่อมสภาพ 32%",
  ui_story_5061_50611201_31_dialog_content = "(เลขที่ 33... อืม?)",
  ui_story_5061_50611201_32_dialog_content = "(หัวของฉัน...? หัวของฉัน... โมดูลเก็บข้อมูล?)",
  ui_story_5061_50611201_33_dialog_content = "...",
  ui_story_5061_50611201_34_dialog_content = "(เอาล่ะ ณ จุดนี้ มีอะไรให้เสียใจกันอีกหรือ?)",
  ui_story_5061_50611201_35_dialog_content = "(...ฉันเคยนำส่วนต่าง ๆ ออกไปมากมายก่อนหน้านี้แล้ว ความรู้สึกของฉันไม่เหมือนกับชาวออโรเรียนที่มีชีวิตอีกต่อไป...)",
  ui_story_5061_50611201_36_dialog_content = "... ส่วนประกอบที่เสียหายถูกแทนที่แล้ว ระบบทำงานปกติ กำลังไฟผลิต: 19%",
  ui_story_5061_50611201_37_dialog_content = "(แม้ว่าพลังงานจะต่ำ แต่ยังไม่มีเหตุการณ์ฉุกเฉินหรืออุบัติเหตุ)",
  ui_story_5061_50611201_38_dialog_content = "(นอกจากที่นี่แล้ว ยังมีสถานที่อื่น ๆ ที่กำลังดำเนินการอีกมากมาย)",
  ui_story_5061_50611201_39_dialog_content = "(กับฉันหรือไม่กับฉัน มันก็ไม่ค่อยมีความแตกต่าง)",
  ui_story_5061_50611201_40_dialog_content = "(... ที่นี่... ยังมีความหมายอยู่เหรอ?)",
  ui_story_5061_50611201_41_dialog_content = "<color=#e8d9bb>เมื่อส่วนประกอบที่รักษาชีวิตของเธอถูกถอดออกทีละน้อย หมายเลข 33 ต้องเข้าสู่ช่วงการสูญเสียการรับรู้เพื่อรักษาฟังก์ชันการอยู่รอดของเธอ</color>",
  ui_story_5061_50611201_42_dialog_content = "<color=#e8d9bb>เธอจะตื่นขึ้นอีกครั้งในอีกไม่กี่ปีข้างหน้า; ครั้งถัดไปก็จะเป็นหลังจากนั้นกว่าสิบปี, และต่อมาก็เป็นหลายสิบปี...</color>",
  ui_story_5061_50611201_43_dialog_content = "<color=#e8d9bb>100 ปีก่อน ที่สถานีจ่ายพลังงานประกายไฟ หมายเลข ███</color>",
  ui_story_5061_50611201_44_dialog_content = "<color=#e8d9bb><size=45>รัมเบิ้ล—</size></color>",
  ui_story_5061_50611201_45_dialog_content = "(อะไร... เกิดอะไรขึ้น!)",
  ui_story_5061_50611201_46_dialog_content = "(อื้อ... ตื่นจากสถานะสลับตัว หัวปวด... ตรวจวินิจฉัยฉุกเฉิน!)",
  ui_story_5061_50611201_47_dialog_content = "(ที่เก็บพลังงานได้รับความเสียหายที่ไม่สามารถซ่อมแซมได้; ลูมินาความบริสุทธิ์สูงกำลังกระจายออกมา ทำให้เกิด<color=#FFB400>การระเบิดพลังงาน</color> บนพื้นผิว;)",
  ui_story_5061_50611201_48_dialog_content = "(ทำไมถึงเป็นถังเก็บพลังงานนี่ล่ะ? มันเป็นส่วนที่แข็งแกร่งที่สุดของเครื่องมือกักเก็บ... มันจะเสียหายได้อย่างไรเนี่ย...)",
  ui_story_5061_50611201_49_dialog_content = "(... โอ้ ใช่เลย... เพราะมันนานมากแล้ว... พอให้ทุกอย่างสึกหรอก...)",
  ui_story_5061_50611201_50_dialog_content = "(... ผ่านมากี่ปีแล้วนะ? ฉันจำไม่ได้เนื่องจากโมดูลเก็บข้อมูลบางส่วนหายไป...)",
  ui_story_5061_50611201_51_dialog_content = "โรอา—",
  ui_story_5061_50611201_52_dialog_content = "(อิคลิพไซท์อยู่ที่นี่เหรอ?... ใช่ครับ ระบบป้องกันล้มเหลวนานแล้ว..)",
  ui_story_5061_50611201_53_dialog_content = "(...ทุกอย่างที่นี่...เสียหายหมดแล้ว...)",
  ui_story_5061_50611201_54_dialog_content = "(อ๊ากก... ที่สุด... ทุกอย่างจะจบลงแล้วเหรอ...)",
  ui_story_5061_50611201_55_dialog_content = "(ในช่วงสุดท้าย ไม่มีใครรู้ถึงสิ่งที่ฉันได้ทำมาตลอดหลายปี...)",
  ui_story_5061_50611201_56_dialog_content = "(ฉันยอมรับชะตากรรมของตัวเองที่จะพังทลายไปพร้อมกับที่นี่นานแล้ว...)",
  ui_story_5061_50611201_57_dialog_content = "(แต่ไม่มีใครรู้ถึงการมีอยู่ของฉัน ไม่มีใครตระหนักถึงสิ่งที่ฉันได้สนับสนุน...)",
  ui_story_5061_50611201_58_dialog_content = "(ใครก็ได้... อย่างน้อยก็มา... แล้วมองฉันเสียนิดหน่อยสิ...)",
  ui_story_5061_50611201_59_dialog_content = "(ใครก็ได้...)",
  ui_story_5061_50611201_60_dialog_content = "ฉันอยู่ที่ไหน...?",
  ui_story_5061_50611201_61_dialog_content = "!",
  ui_story_5061_50611201_62_dialog_content = "หืม? คุณ... เป็นออโรเรียนหรือเปล่า?",
  ui_story_5061_50611201_63_dialog_content = "—",
  ui_story_5061_50611201_64_dialog_content = "(เทมเพลตเอคโค่ของฉันไม่สามารถสนับสนุนให้ฉันสามารถส่งเสียงออกมาได้อีกต่อไป ดังนั้นฉันสามารถแค่ยื่นมือออกไปโดยสัญชาตญาณเท่านั้น...)",
  ui_story_5061_50611201_65_dialog_content = "(ฉันยื่นมือไปหาคนที่ช่วยฉันหลุดพ้นความเหงาที่ไม่มีที่สิ้นสุด—นางสาวอลิน่า)",
  ui_story_5061_50611201_66_dialog_content = "(ฉันใช้ \"ส่วนหนึ่ง\" ของนางอลิน่าในการซ่อมเทมเพลตเอคโค่ของฉัน ทำให้ฉันสามารถส่งเสียงได้..)",
  ui_story_5061_50611201_67_dialog_content = "(ฉันเล่าเรื่องภารกิจของฉันให้เธอฟัง และเธอก็บอกเรื่องที่เกิดขึ้นบนพื้นผิวโลกให้ฉันฟัง)",
  ui_story_5061_50611201_68_dialog_content = "(การระเบิดพลังงานที่เกิดจากความเสียหายของเครื่องมือกัดก้อนลูมินา ถูกเรียกว่า <color=#FFB400>พายุแสงเหนือ</color> โดยคนที่อยู่ด้านนอก)",
  ui_story_5061_50611201_69_dialog_content = "ลูมินาผิดปกติที่เกิดจากออโรร่าตอร์มดึงดูดอิคลิพไซท์จำนวนมากมาย",
  ui_story_5061_50611201_70_dialog_content = "(ความเสื่อมของสถานที่... ส่งผลให้เกิดความผิดปกติในลูมินาภายนอก อิคลิพไซท์วิ่งเต็มที่ และทำให้ชีวิตของออโรเรียนบนผิวดินตกอยู่ในความเสี่ยง)",
  ui_story_5061_50611201_71_dialog_content = "(ฉันเสมอคิดว่าภารกิจของฉันคือการรักษาให้อุปกรณ์ทำงานได้ตลอดเวลา)",
  ui_story_5061_50611201_72_dialog_content = "(แต่จริง ๆ แล้ว จุดประสงค์ของฉันคือการรักษาสภาพแวดล้อมเพื่อการอยู่อาศัยของชาวออโรเรียนหรือไม่?)",
  ui_story_5061_50611201_73_dialog_content = "ฉันขอโทษ แต่ฉันไม่สามารถออกจากที่นี่ได้ การตัดการเชื่อมต่ออาจทำให้ความไม่เสถียรของสถานที่นี้ยิ่งแย่ลง",
  ui_story_5061_50611201_74_dialog_content = "แม้ว่าสภาพของสถานที่นี้จะไม่เป็นปัญหาสำหรับฉันอีกต่อไป ฉันก็ไม่ต้องการให้โลกภายนอกต้องทนภัยพิบัติที่น่ากลัวมากขึ้นเมื่อเทียบกับที่มีอยู่แล้ว",
  ui_story_5061_50611201_75_dialog_content = "ไม่มีทางอื่นแล้วจริงๆเหรอ?",
  ui_story_5061_50611201_76_dialog_content = "... ด้วยอุปกรณ์ที่นี่ ฉันสามารถเน้นลูมินาที่พุ่งออกมาที่นี่ไปยังคุณ ทำให้คุณสามารถปล่อยพลังนี้ไปยังอิคลิพไซท์ที่อยู่ข้างนอก...",
  ui_story_5061_50611201_77_dialog_content = "ด้วยวิธีนี้ คุณสามารถขับไล่ฝูง Eclipsite ในขณะที่หยุดให้พายุ Aurorastorm ขยายตัว",
  ui_story_5061_50611201_78_dialog_content = "แต่ร่างกายของออโรเรียนไม่สามารถทนต่อปริมาณพลังงานมากขนาดนี้ ซึ่งหมายความว่าคุณอาจจะสลายตัวภายในเวลาไม่กี่นาที",
  ui_story_5061_50611201_79_dialog_content = "(แสงสว่างเดียวที่ฉันปรารถนามาตลอดช่วงเวลายาวนี้ ฉันจะส่งมันไปด้วยมือของตัวเองจริง ๆ หรือ...)",
  ui_story_5061_50611201_80_dialog_content = "... ไม่เป็นไร ยังไงเราก็ไม่มีทางเลือกอื่นเหลือแล้ว",
  ui_story_5061_50611201_81_dialog_content = "(ขอร้องนะ ฉันขอร้องอย่าสละตัวเสียให้ คุณคือแสงสว่างที่ฉันรอคอยอย่างยากลำบาก)",
  ui_story_5061_50611201_82_dialog_content = "คุณคิดดีแล้วจริงๆ ใช่ไหม?",
  ui_story_5061_50611201_83_dialog_content = "คุณปกป้องที่นี่มานานแล้ว... แต่ตอนนี้ถึงเวลาให้หนึ่งในพวกเราปกป้องคุณ",
  ui_story_5061_50611201_84_dialog_content = "ไม่เพียงแต่นั้น... แต่ฉันยังต้องการปกป้องโลกของเราเพื่อเป็นเกียรติแก่น้องสาวของฉันด้วย",
  ui_story_5061_50611201_85_dialog_content = "(ไม่... ฉันไม่อยากเสียคุณไป!)",
  ui_story_5061_50611201_86_dialog_content = "ฉันชื่นชมความกล้าหาญของคุณ มาเริ่มกันเถอะ...",
  ui_story_5061_50611201_87_dialog_content = "นี่ต้องเป็น... ความทรงจำของหมายเลข 33 แน่นอน!",
  ui_story_5061_50611201_88_dialog_content = "ทำงานได้หรือเปล่า, PlayerName?",
  ui_story_5061_50611201_89_dialog_content = "ใช่เลย! ความทรงจำของเธอกำลังอยู่ในกระบวนการฟื้นฟู!",
  ui_story_5061_50611201_90_dialog_content = "ใช่ ฉันจำได้แล้ว ภารกิจของฉันไม่ใช่แค่ปกป้องสถานที่นี้เท่านั้น...",
  ui_story_5061_50611201_91_dialog_content = "และยังคอยปกป้องโลกภายนอกด้วยหรือ? อลิน่า—",
  ui_story_5061_50611201_92_dialog_content = "เกิดข้อผิดพลาดในเทมเพลตเอคโค่!",
  ui_story_5061_50611201_93_dialog_content = "งั้นทำไมเธอไม่ดีขึ้นล่ะ?",
  ui_story_5061_50611201_94_dialog_content = "ฉันต้องใช้พลังของฉันอีกครั้ง! ครั้งนี้ฉันมั่นใจว่าฉันสามารถสัมผัสถึงแกนกลางของจิตใจเธอได้!",
  ui_story_5061_50611201_95_dialog_content = "บังคับปิดโมดูลหน่วยความจำ...",
  ui_story_5061_50611201_96_dialog_content = "อย่า! ไม่! ฉันไม่อยากลืมเธอเลย!",
  ui_story_5061_50611201_97_dialog_content = "<size=45>ช่วยฉัน! ช่วยฉัน! อ๊าาาาา!</size>",
  ui_story_5061_50611202_1_dialog_content = "อื้อออ...",
  ui_story_5061_50611202_2_dialog_content = "เธอหยุดแล้ว!",
  ui_story_5061_50611202_3_dialog_content = "คุณต้องช่วยเธอ PlayerName!",
  ui_story_5061_50611202_4_option_content = "บูสต์พลัง",
  ui_story_5061_50611202_5_dialog_content = "<color=#e8d9bb>ในทะเลของความตื่นตัวที่ลึกลับไม่มีที่สิ้นสุด ร่างบางๆ งอกอยู่</color>",
  ui_story_5061_50611202_6_dialog_content = "ฉัน... ภารกิจของฉัน, ภารกิจของฉันคือ...",
  ui_story_5061_50611202_7_dialog_content = "เครื่องมือรวมลูมินาถูกทิ้งไปแล้ว! ตอนนี้ที่ต้องทำคือปิดมันและปิดที่นี่ลง",
  ui_story_5061_50611202_8_dialog_content = "ฉันรู้ว่ามันยากสำหรับคุณตลอดหลายปีที่ผ่านมา แต่ภารกิจของคุณเสร็จสิ้นในที่สุดแล้ว",
  ui_story_5061_50611202_9_dialog_content = "...!",
  ui_story_5061_50611202_10_dialog_content = "ฉันขอโทษที่ใช้เวลานานในการหาคุณ คุณคงรู้สึกเหงามากตลอดเวลานี้",
  ui_story_5061_50611202_11_dialog_content = "ทำไม! ทำไมคุณถึงมาหาฉันตอนนี้เท่านั้นล่ะ?",
  ui_story_5061_50611202_12_dialog_content = "ลูมินาถูกกีดขวางมานานเกินนับ โบราณวัตถุถูกทำลายมานาน และฉันก็ผิดพลาดมานานเช่นกัน...",
  ui_story_5061_50611202_13_dialog_content = "ฉันตัดสินใจยอมแพ้แล้ว...",
  ui_story_5061_50611202_14_dialog_content = "แต่คุณไม่เคยยอมแพ้ใช่ไหม และเพราะเช่นนั้น เราจะขอบคุณคุณตลอดไป",
  ui_story_5061_50611202_15_dialog_content = "...",
  ui_story_5061_50611202_16_dialog_content = "นอร์ธแลนด์ได้รับความสงบสุขมาหลายปีแล้ว เพราะคุณไม่เคยยอมแพ้",
  ui_story_5061_50611202_17_dialog_content = "สถานที่ที่ไม่ได้รับความคุ้มครองจากเหล่าซากปรักหักพังนี้ถูกอิคลิพไซท์บุกครอบครองในไม่ช้าเลยทีเดียว",
  ui_story_5061_50611202_18_dialog_content = "แต่ประชาชนแห่งนอร์ธแลนด์ได้ใช้ชีวิตอย่างมีความสุขและสงบสุขมานาน... และทั้งหมดนี้เป็นเพราะคุณ",
  ui_story_5061_50611202_19_dialog_content = "... จริงๆ นะ เพราะฉัน?",
  ui_story_5061_50611202_20_dialog_content = "ภารกิจของฉัน...มีความหมายเหรอ?",
  ui_story_5061_50611202_21_dialog_content = "แน่นอนเลย! ภารกิจของคุณมีผลกระทบต่อทั้งนอร์ธแลนด์ และออโรเรียนทุกคนที่อาศัยอยู่ที่นี่!",
  ui_story_5061_50611202_22_dialog_content = "การมาถึงจุดสิ้นสุดไม่ใช่วัตถุประสงค์ของภารกิจของคุณ... ความหมายที่แท้จริงคือทุกช่วงเวลาที่คุณนำความสงบสุขมาให้กับประชาชนในราชอาณาจักรนี้",
  ui_story_5061_50611202_23_dialog_content = "ขอบคุณนะ... ขอบคุณสำหรับทุกอย่างที่เธอทำเพื่อพวกเรา",
  ui_story_5061_50611202_24_dialog_content = "ขอบคุณมากนะ",
  ui_story_5061_50611202_25_dialog_content = "...ฉันจำได้ว่า... ครั้งหนึ่ง... มีคนเจอฉันแบบนี้เหมือนกัน...",
  ui_story_5061_50611202_26_dialog_content = "... ขอบคุณฉันสำหรับความพยายามและยังกลายเป็นเพื่อนสนิทของฉันด้วย",
  ui_story_5061_50611202_27_dialog_content = "และยังมีคนอื่น ๆ อีกมากมายที่อยากเป็นเพื่อนกับคุณด้วย! คุณไม่ต้องแบกภาระนี้คนเดียวอีกต่อไป!",
  ui_story_5061_50611202_28_dialog_content = "ทุกคนที่นี่ยินดีที่จะสู้คู่ข้างคุณ!",
  ui_story_5061_50611202_29_dialog_content = "... แต่ฉัน... หลังจากออกจากการต่อสู้ อุปกรณ์เชื่อมต่อทั้งหมดหยุดทำงานแล้ว",
  ui_story_5061_50611202_30_dialog_content = "...ตอนนี้ฉันก็เป็นแค่เศษเหล็กไร้ความหมายเท่านั้นเอง",
  ui_story_5061_50611202_31_dialog_content = "... ฉันไม่มีประโยชน์ให้คุณเลย",
  ui_story_5061_50611202_32_dialog_content = "ไม่ใช่เลยนะ หัวใจของคุณ คำพูดของคุณ จิตใจของคุณ... ทุกอย่างเหล่านี้ช่วยให้เรามีพลังและทำให้โลกนี้ดีขึ้น",
  ui_story_5061_50611202_33_dialog_content = "หัวใจ? ใจความ? คุณหมายถึง... คุณต้องการยูนิตเก็บของของฉันเหรอ? อวัยวะภายในหรือภายนอก?",
  ui_story_5061_50611202_34_dialog_content = "ฉัน, เอิ่ม... ฉันคิดว่ามันไม่ได้มีความแตกต่างจริง ๆ! เฮ้, คุณสามารถบอกฉันได้มั้ย? นอร์ธแลนด์เคยเป็นที่อบอุ่นในอดีตหรือเปล่า?",
  ui_story_5061_50611202_35_dialog_content = "มันอบอุ่นเมื่อกี้",
  ui_story_5061_50611202_36_dialog_content = "ทำไมถึงเป็นแบบนี้ล่ะ?",
  ui_story_5061_50611202_37_dialog_content = "เนื่องจากตำแหน่งของวงแหวนสนธยาที่แตกต่างกัน ในอดีตของโลกนี้ ไม่มีสิ่งที่เรียกว่ากลางวันนิรันดร์และคืนนิรันดร์",
  ui_story_5061_50611202_38_dialog_content = "เอาล่ะ ดังนั้นแอนโทนี่ถูกต้องตั้งแต่แรกเลย! ขอบคุณมากเลยครับ หมายเลข 33! คุณเพิ่งให้คำตอบที่สำคัญมากเกี่ยวกับอดีตของโลก!",
  ui_story_5061_50611202_39_dialog_content = "อย่างไรก็ตาม ฉันไม่รู้ว่าทำไมมันเป็นแบบนี้ และฉันไม่สามารถให้คำตอบที่แน่นอนให้คุณได้",
  ui_story_5061_50611202_40_dialog_content = "นั่นก็ดีนะ! การค้นพบความจริงคือเป้าหมายของการเดินทางของเรา มันเป็นสิ่งที่ชาวออโรเรียนทุกคนรู้ในทางหนึ่งหรืออีกทางหนึ่ง",
  ui_story_5061_50611202_41_dialog_content = "เข้าใจแล้ว",
  ui_story_5061_50611202_42_dialog_content = "เอาล่ะ... อยากไปด้วยกันกับเรามั้ย?",
  ui_story_5061_50611202_43_dialog_content = "หืม?",
  ui_story_5061_50611202_44_dialog_content = "แน่นอน! ท้ายที่สุดแล้วคุณก็เป็นส่วนหนึ่งของโลกของเราด้วย คุณอยากสัมผัสประสบการณ์ด้วยตัวเองไหมล่ะ?",
  ui_story_5061_50611202_45_dialog_content = "เอาเข้า! ก้าวแรกมันยากเสมอ แต่คุณจะไม่เป็นไรหรอก!",
  ui_story_5061_50611202_46_dialog_content = "... แต่... อุปกรณ์เชื่อมต่อของฉัน... ฉันสูญเสียความสามารถในการรับสัญญาณภายนอกแล้ว... ฉัน...",
  ui_story_5061_50611202_47_dialog_content = "เดินทีละก้าวเท่านั้น และฉันสัญญาว่าคุณจะไม่ล้มลง",
  ui_story_5061_50611202_48_dialog_content = "พวกเขาไม่เรียกฉันว่าผู้นำทางโดยไม่มีเหตุผลนะครับ! ฉันจะเป็นตาของคุณ ดังนั้นเพียงแค่ยกหัวขึ้น!",
  ui_story_5061_50611202_49_dialog_content = "นี่มัน...",
  ui_story_5061_50611202_50_dialog_content = "ตัวส่งสัญญาณที่ประดิษฐ์ขึ้นอย่างรวดเร็วและไม่เป็นระเบียบ... ถูกตั้งค่าให้สอดคล้องกับช่องสื่อสารของฉันเป็นพิเศษ...",
  ui_story_5061_50611202_51_dialog_content = "พร้อมหรือยัง? สาม, สอง, หนึ่ง...",
  ui_story_5061_50611202_52_dialog_content = "ยินดีต้อนรับสู่โลกภายนอก!",
  ui_story_5061_50611202_53_dialog_content = "โทษทีนะ เราไม่ได้มีโอกาสแนะนำตัวเองอย่างเป็นทางการกันก่อนหน้านี้",
  ui_story_5061_50611202_54_dialog_content = "นี่คือมาสเตอร์โนวิโอ ภูตเขาแห่งนอร์ธแลนด์ โล่ของเขาปกป้องลูมินาของเราจากการถูกดูดซับเมื่อสักครู่นี้",
  ui_story_5061_50611202_55_dialog_content = "นั่นเป็นวิธีที่ PlayerName สามารถใช้พลังของเขากับ No. 33 โดยไม่ถูกโต้ตอบค่ะ",
